        internal static BossMoveProfile[] CreateMawMoves() => new[]
        {
            MawProfile("weapon", "第1記憶が敵に命中したとき、命中方向の角度120°・範囲3mの扇状に、攻撃力・魔力の高い方の18%の闇属性ダメージを与える。再発動まで4秒かかり、ダッシュや無敵の効果はない。", "When your first memory hits an enemy, deal Dark damage equal to 18% of whichever is higher: your Attack or Ability Power, in a 120° fan extending 3m toward the hit. Cooldown: 4 seconds. Does not grant a dash or invulnerability.", "当第1记忆命中敌人时，朝命中方向以角度120°、范围3m的扇形，造成相当于攻击力与法术强度中较高一方18%的暗属性伤害。冷却4秒，不带冲刺或无敌效果。",
                new[] { C("MawBite",BossMawBalance.MawBiteValue,BossMawBalance.MawBiteCap) }, MawFan("MawBite",BossMawBalance.WeaponA0CooldownMillis,BossMawBalance.WeaponA0RangeMilli,BossMawBalance.WeaponA0AngleMilli)),
            MawProfile("armor", "敵からHPダメージを受けたとき、「攻撃力・魔力の高い方の14%」と「失ったHPの15%」のうち低い方の値の障壁を、2秒間得る。障壁は重ならず、戦闘中以外には自動で蓄積しない。再発動まで6秒かかる。", "When an enemy deals HP damage to you, gain a shield for 2 seconds equal to the lower of 14% of the higher of your Attack and Ability Power and 15% of your missing HP. Cooldown: 6 seconds. Does not stack or automatically build up outside combat.", "受到敌人的生命伤害时，获得持续2秒的护盾，其值为“攻击力与法术强度中较高一方的14%”与“已损失生命的15%”中较低的一方。护盾不叠加，战斗外也不会自动积累。冷却6秒。",
                new[] { C("MawConversion",BossMawBalance.MawConversionValue,BossMawBalance.MawConversionCap,BossCoefficientKind.Shield) },
                new BossAction(BossEvent.NativeDamageTaken,BossMechanism.Defense,BossPayload.Shield,"MawConversion",cooldownMillis:BossMawBalance.ArmorA0CooldownMillis,lifetimeMillis:BossMawBalance.ArmorA0LifetimeMillis,maxTargets:BossMawBalance.ArmorA0MaxTargets,maxInstances:BossMawBalance.ArmorA0MaxInstances,magnitudeMilli:BossMawBalance.ArmorA0MagnitudeMilli)),
            MawProfile("charm", "第1記憶が敵に4回命中するごとに、「攻撃力・魔力の高い方の6%」と「失ったHPの8%」のうち低い方の値だけ、自身を回復する。命中の回数は最大3回までたまり、最後の命中から4秒経つとリセットされる。再発動まで5秒かかる。1回の攻撃で複数の敵に命中しても、数えるのも回復するのも1回だけである。", "Every fourth hit on an enemy with your first memory heals you for the lower of 6% of the higher of your Attack and Ability Power and 8% of your missing HP. Store up to 3 hits; the count resets 4 seconds after the last hit. Cooldown: 5 seconds. Hitting multiple enemies with one attack only counts once and heals once.", "第1记忆每命中敌人4次，回复自身，其值为“攻击力与法术强度中较高一方的6%”与“已损失生命的8%”中较低的一方。命中次数最多储存3次，最后一次命中4秒后重置。冷却5秒。一次攻击命中多个敌人也只计1次、只回复1次。",
                new[] { C("MawGreatjaw",BossMawBalance.MawGreatjawValue,BossMawBalance.MawGreatjawCap,BossCoefficientKind.Heal) },
                new BossAction(BossEvent.MainHit,BossMechanism.Defense,BossPayload.Heal,"MawGreatjaw",cooldownMillis:BossMawBalance.CharmA0CooldownMillis,mainHits:BossMawBalance.CharmA0MainHits,counterLifetimeMillis:BossMawBalance.CharmA0CounterLifetimeMillis,maxTargets:BossMawBalance.CharmA0MaxTargets,maxInstances:BossMawBalance.CharmA0MaxInstances,magnitudeMilli:BossMawBalance.CharmA0MagnitudeMilli)),
            MawProfile("head", "第2記憶を発動したとき、発動方向へ2本の斬撃波を0.15秒間隔で放つ。斬撃波は幅1m、射程6m、持続0.6秒で直進し、攻撃力・魔力の高い方の8%の闇属性ダメージを与える。追尾はしない。再発動まで6秒かかる。", "When you use your second memory, release 2 slash waves in its direction, 0.15 seconds apart. Each travels straight ahead, is 1m wide, has a 6m range, lasts 0.6 seconds, and deals Dark damage equal to 8% of whichever is higher: your Attack or Ability Power. Cooldown: 6 seconds. The waves do not home in on enemies.", "发动第2记忆时，朝发动方向放出2道斩击波，间隔0.15秒。斩击波宽1m、射程6m、持续0.6秒并直线前进，造成相当于攻击力与法术强度中较高一方8%的暗属性伤害。不会追踪敌人。冷却6秒。",
                new[] { C("MawStance",BossMawBalance.MawStanceValue,BossMawBalance.MawStanceCap) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.Projectile,BossPayload.Damage,"MawStance",cooldownMillis:BossMawBalance.HeadA0CooldownMillis,lifetimeMillis:BossMawBalance.HeadA0LifetimeMillis,maxTargets:BossMawBalance.HeadA0MaxTargets,maxInstances:BossMawBalance.HeadA0MaxInstances,rangeMilli:BossMawBalance.HeadA0RangeMilli,widthMilli:BossMawBalance.HeadA0WidthMilli,speedMilli:BossMawBalance.HeadA0SpeedMilli,element:BossElement.Dark),
                new BossAction(BossEvent.Clock,BossMechanism.Projectile,BossPayload.Damage,"MawStance",delayMillis:BossMawBalance.HeadA1DelayMillis,lifetimeMillis:BossMawBalance.HeadA1LifetimeMillis,maxTargets:BossMawBalance.HeadA1MaxTargets,maxInstances:BossMawBalance.HeadA1MaxInstances,rangeMilli:BossMawBalance.HeadA1RangeMilli,widthMilli:BossMawBalance.HeadA1WidthMilli,speedMilli:BossMawBalance.HeadA1SpeedMilli,element:BossElement.Dark)),
            MawProfile("hands", "第1記憶で敵のHPに与えた実際のダメージの10%を、HPとして吸収する。1回の攻撃判定ごとの上限は攻撃力・魔力の高い方の4%で、再発動まで4秒かかる。無敵の敵、味方、反射ダメージ、派生ダメージからは回復しない。", "Restore HP equal to 10% of the actual HP damage your first memory deals to enemies, up to 4% of the higher of your Attack and Ability Power per hit. Cooldown: 4 seconds. Hits against invulnerable targets or allies, reflected damage, and damage from additional triggered effects do not heal you.", "吸收第1记忆对敌人生命造成的实际伤害的10%，作为生命回复。每次攻击判定的上限为攻击力与法术强度中较高一方的4%，冷却4秒。对无敌敌人、队友的命中，以及反射伤害、派生伤害不会带来回复。",
                new[] { C("MawDevour",BossMawBalance.MawDevourValue,BossMawBalance.MawDevourCap,BossCoefficientKind.Heal) },
                new BossAction(BossEvent.MainHit,BossMechanism.Defense,BossPayload.Heal,"MawDevour",cooldownMillis:BossMawBalance.HandsA0CooldownMillis,maxTargets:BossMawBalance.HandsA0MaxTargets,maxInstances:BossMawBalance.HandsA0MaxInstances,magnitudeMilli:BossMawBalance.HandsA0MagnitudeMilli)),
            MawProfile("feet", "移動が終わってから2秒以内に行う次の第1記憶が命中したとき、角度90°・範囲3mの扇状に、攻撃力・魔力の高い方の18%の闇属性ダメージを与える。再発動まで5秒かかり、無敵にも対象指定不可にもならず、追加のダッシュもない。", "If you next use your first memory within 2 seconds of finishing movement, its hit deals Dark damage equal to 18% of whichever is higher: your Attack or Ability Power, in a 90° fan extending 3m. Cooldown: 5 seconds. Does not grant invulnerability, untargetability, or an additional dash.", "移动结束后2秒内使用第1记忆并命中时，以角度90°、范围3m的扇形，造成相当于攻击力与法术强度中较高一方18%的暗属性伤害。冷却5秒，不会带来无敌或不可选中，也没有追加冲刺。",
                new[] { C("MawShadowbite",BossMawBalance.MawShadowbiteValue,BossMawBalance.MawShadowbiteCap) },
                new BossAction(BossEvent.MovementCompleted,BossMechanism.Ledger,BossPayload.ArrivalWindow,lifetimeMillis:BossMawBalance.FeetA0LifetimeMillis,maxTargets:BossMawBalance.FeetA0MaxTargets,maxInstances:BossMawBalance.FeetA0MaxInstances), MawFan("MawShadowbite",BossMawBalance.FeetA1CooldownMillis,BossMawBalance.FeetA1RangeMilli,BossMawBalance.FeetA1AngleMilli)),
            MawProfile("stage2", "第1記憶が3回命中するごとに、前方の角度120°・範囲3mの扇状に、攻撃力・魔力の高い方の18%の闇属性ダメージを与える。命中の回数は最後の命中から4秒経つとリセットされる。再発動まで3秒かかる。自身のHPが50%以下のときは、前後に角度90°の扇状の波を放ち、それぞれ攻撃力・魔力の高い方の9%の闇属性ダメージを与える。", "Every third hit with your first memory deals Dark damage equal to 18% of whichever is higher: your Attack or Ability Power, in a forward 120° fan extending 3m. The hit count resets 4 seconds after the last hit. Cooldown: 3 seconds. At 50% HP or less, instead release 90° fan-shaped waves in front of and behind you, each dealing Dark damage equal to 9% of the higher of your Attack and Ability Power.", "第1记忆每命中3次，在前方以角度120°、范围3m的扇形，造成相当于攻击力与法术强度中较高一方18%的暗属性伤害。命中次数在最后一次命中4秒后重置。冷却3秒。自身生命在50%以下时，改为在前后放出角度90°的扇形波，各造成相当于攻击力与法术强度中较高一方9%的暗属性伤害。",
                new[] { C("MawCycleBite",BossMawBalance.MawCycleBiteValue,BossMawBalance.MawCycleBiteCap) }, MawFan("MawCycleBite",BossMawBalance.Stage2A0CooldownMillis,BossMawBalance.Stage2A0RangeMilli,BossMawBalance.Stage2A0AngleMilli), MawFan("MawCycleBite",BossMawBalance.Stage2A1CooldownMillis,BossMawBalance.Stage2A1RangeMilli,BossMawBalance.Stage2A1AngleMilli,BossEvent.Clock)),
            MawProfile("stage3", "3回目の命中地点（自身から8m以内）に半径2.5mの煉獄領域を展開し、0.5秒の予告の後、攻撃力・魔力の高い方の22%の闇属性爆発ダメージを1回与える。再発動まで5秒かかる。自身のHPが50%以下のときは、領域は自身の足元に発生する。", "On the third hit, create a Purgatory field with a 2.5m radius at the hit location within 8m of you. After a 0.5-second warning, it explodes once, dealing Dark damage equal to 22% of whichever is higher: your Attack or Ability Power. Cooldown: 5 seconds. At 50% HP or less, the field appears at your feet instead.", "第3次命中时，在命中地点（自身8m以内）展开半径2.5m的炼狱领域，0.5秒预警后爆炸1次，造成相当于攻击力与法术强度中较高一方22%的暗属性伤害。冷却5秒。自身生命在50%以下时，领域改为在自身脚下出现。",
                new[] { C("MawPurgatory",BossMawBalance.MawPurgatoryValue,BossMawBalance.MawPurgatoryCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"MawPurgatory",anchor:BossAnchor.Hit,cooldownMillis:BossMawBalance.Stage3A0CooldownMillis,delayMillis:BossMawBalance.Stage3A0DelayMillis,maxTargets:BossMawBalance.Stage3A0MaxTargets,maxInstances:BossMawBalance.Stage3A0MaxInstances,radiusMilli:BossMawBalance.Stage3A0RadiusMilli,rangeMilli:BossMawBalance.Stage3A0RangeMilli,element:BossElement.Dark)),
            MawProfile("stage6", "3回目の命中時、左右±30°の方向へ、角度120°・範囲3.5mの扇状の波を0.20秒間隔で放ち、それぞれ攻撃力・魔力の高い方の45%（合計90%、上限100%）の闇属性ダメージを与える。再発動まで8秒かかる。自身のHPが50%以下のときは、前後の角度90°の扇状波に変わる。さらに、2つの波で敵のHPに与えた実際のダメージの合計の45%だけ、自身を回復する。回復量の上限は攻撃力・魔力の高い方の38%（上限40%）である。", "On the third hit, release 2 waves, 0.20 seconds apart, angled 30° left and right. Each covers a 120° fan extending 3.5m and deals Dark damage equal to 45% of whichever is higher: your Attack or Ability Power (90% total, capped at 100%). Cooldown: 8 seconds. At 50% HP or less, the waves become 90° fans in front of and behind you. Heal for 45% of the total actual HP damage both waves deal to enemies, up to 38% of the higher of your Attack and Ability Power (capped at 40%).", "第3次命中时，朝左右±30°方向以0.20秒间隔放出2道波，各覆盖角度120°、范围3.5m的扇形，造成相当于攻击力与法术强度中较高一方45%（合计90%，上限100%）的暗属性伤害。冷却8秒。自身生命在50%以下时，波变为前后角度90°的扇形波。此外，按两道波对敌人生命造成的实际伤害合计的45%回复自身，回复量上限为攻击力与法术强度中较高一方的38%（上限40%）。",
