        };
        internal static BossRewardProfile[] CreateMawRewards()
        {
            var heal = new BossRewardAction(BossRewardActionKind.NativeHeal,BossMawBalance.RewardHealValueMilli,BossMawBalance.RewardHealCapMilli,cooldownMillis:BossMawBalance.RewardHealCooldownMillis,count:BossMawBalance.RewardHealCount,magnitudeMilli:BossMawBalance.RewardHealMagnitudeMilli);
            var shield = new BossRewardAction(BossRewardActionKind.NativeShield,BossMawBalance.RewardShieldValueMilli,BossMawBalance.RewardShieldCapMilli,cooldownMillis:BossMawBalance.RewardShieldCooldownMillis,count:BossMawBalance.RewardShieldCount,order:1,magnitudeMilli:BossMawBalance.RewardShieldMagnitudeMilli);
            var cooldown = new BossRewardAction(BossRewardActionKind.NativeState,BossMawBalance.RewardCooldownValueMilli,BossMawBalance.RewardCooldownCapMilli,cooldownMillis:BossMawBalance.RewardCooldownCooldownMillis,count:BossMawBalance.RewardCooldownCount,order:2,magnitudeMilli:BossMawBalance.RewardCooldownMagnitudeMilli);
            return new[] { new BossRewardProfile(MawRewardId,MawSetId,"St_U_BigChomp",BossRewardAdapter.BigChomp,new[]
            {
                new BossRewardStage(1,new Txt("自身の「Big Chomp」が生存している敵に命中したとき、敵の重みを記録する。重みは通常の敵が1、ボスはそれより大きく、最大3まで。ディレイ後の回復量には、「攻撃力・魔力の高い方の8%」と「1ヒットあたりの元の回復量×重み×20%」のうち低い方の値が加算される。共有の再発動まで8秒かかる。味方への命中数や本体の回復処理は変わらない。", "When your Big Chomp hits a living enemy, count normal enemies as 1 and bosses as more, up to a total weight of 3. After its delay, increase its healing by the lower of 8% of the higher of your Attack and Ability Power and its original healing per hit × weight × 20%. Shared Cooldown: 8 seconds. Ally hit counts and the skill's original healing remain unchanged.", "自身的“Big Chomp”命中存活的敌人时，记录敌人的权重。权重为普通敌人1、Boss更大，最高3。延迟后的回复量会加上“攻击力与法术强度中较高一方的8%”与“每次命中的原回复量×权重×20%”中较低的一方。共享冷却8秒。对队友的命中数与本体的回复处理不变。"),new[] { heal }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、同じスキルのディレイ後に付与する障壁量にも、「攻撃力・魔力の高い方の10%」と「1ヒットあたりの元の障壁量×重み×20%」のうち低い方の値が加算される。持続時間は元のままで、共有の8秒の枠で1回だけ発動する。", "In addition to boss reward stage 1, increase Big Chomp's shield after its delay by the lower of 10% of the higher of your Attack and Ability Power and its original shield amount per hit × weight × 20%. The shield's duration is unchanged. Triggers only once per shared 8-second Cooldown.", "在固有奖励阶段1的效果之上，同一技能延迟后赋予的护盾量也会加上“攻击力与法术强度中较高一方的10%”与“每次命中的原护盾量×权重×20%”中较低的一方。持续时间维持原样，每个共享的8秒窗口只发动1次。"),new[] { heal,shield }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、同じスキルのディレイが終わるとき、自身のクールダウン短縮効果に「0.50秒」と「重み×0.25秒」のうち低い方の値が加わる。元の短縮量が0のときは加算しない。共有の8秒の枠を使い、他の記憶への短縮や新たなHP吸収はない。", "In addition to boss reward stage 2, when Big Chomp's delay ends, increase its Cooldown reduction for you by the lower of 0.50 seconds and weight × 0.25 seconds. Adds nothing if the original reduction is 0. Shares the 8-second Cooldown. Does not reduce other memories' Cooldowns or add HP absorption.", "在固有奖励阶段2的效果之上，同一技能的延迟结束时，自身的冷却缩短效果会加上“0.50秒”与“权重×0.25秒”中较低的一方。原缩短量为0时不加算。使用共享的8秒窗口，不会缩短其他记忆的冷却，也不追加生命吸收。"),new[] { heal,shield,cooldown })
            }) };
        }
